
(function(){
  try {
    const daiana='data:image/png;base64,';
    const tathiana='data:image/png;base64,';
    if (typeof GEO_AGENT_PHOTOS !== 'undefined') {
      GEO_AGENT_PHOTOS['Daiana Cândido Rodrigues']=daiana;
      GEO_AGENT_PHOTOS['Tathiana Innocencio Salsa Rosa']=tathiana;
    }
    if (typeof GEO_AGENT_PHOTO_POS !== 'undefined') {
      GEO_AGENT_PHOTO_POS['Daiana Cândido Rodrigues']='50% 24%';
      GEO_AGENT_PHOTO_POS['Tathiana Innocencio Salsa Rosa']='50% 25%';
    }
    const rerender=()=>{
      try { if (typeof geoRender==='function') geoRender(); } catch(e){}
      try { if (typeof geoRefreshMap==='function') geoRefreshMap(); } catch(e){}
      try { if (typeof geo3dUpdatePoints==='function' && typeof geoVisiblePoints==='function') geo3dUpdatePoints(geoVisiblePoints()); } catch(e){}
      try {
        const drawer=document.getElementById('detailDrawer');
        if(drawer && drawer.classList.contains('open')){
          const school=drawer.querySelector('h3')?.textContent?.trim();
          if (school && typeof geoOpenDetails==='function') geoOpenDetails(school);
        }
      } catch(e){}
    };
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', rerender, {once:true});
    else setTimeout(rerender, 60);
  } catch (err) { console.error('v204 photo fix', err); }
})();
